"wraps" => {
    let wrapped = a1(&a, name)?;
    let default_assigned = || tup(vec![s("__module__"), s("__name__"), s("__qualname__"), s("__annotations__"), s("__doc__")]);
    let default_updated = || tup(vec![s("__dict__")]);
    let assigned = match a.kw("assigned").or_else(|| a.p.get(1).cloned()) {
        Some(v) => v,
        None => default_assigned(),
    };
    let updated = match a.kw("updated").or_else(|| a.p.get(2).cloned()) {
        Some(v) => v,
        None => default_updated(),
    };
    a.no_kw? / want check
    builtin("wraps", move |a: Args| {
        let wrapper = a1(&a, "wraps")?;
        for x in iter(&assigned)? {
            let n = to_str(&x)?;
            match getattr(&wrapped, &n) {
                Ok(v) => setattr(&wrapper, sym(&n), v)?,
                Err(E(e)) if is_exc(&e, "AttributeError") => {}
                Err(e) => return Err(e),
            }
        }
        // updated
        for x in iter(&updated)? {
            let n = to_str(&x)?;
            if n == "__dict__" {
                // merge wrapped's function attrs into wrapper's attrs
                match (&wrapper, &wrapped) {
                    (V::Func(wf), V::Func(ff)) => {
                        let vals: Vec<(Sym, V)> = ff.attrs.borrow().iter().cloned().collect();
                        let mut wa = wf.attrs.borrow_mut();
                        for (k, v) in vals {
                            match wa.iter_mut().find(|(kk, _)| *kk == k) {
                                Some(e) => e.1 = v,
                                None => wa.push((k, v)),
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
        setattr(&wrapper, sym("__wrapped__"), wrapped.clone())?;
        Ok(wrapper)
    })
}
